function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'StreamChecker' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with StreamChecker(words).';
  const words = args[0][0];
  if (!Array.isArray(words) || words.length < 1 || words.length > 2000) return 'words needs 1 to 2000 entries.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 200) return 'Each word has 1 to 200 letters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use lowercase English letters only.';
  }
  if (operations.length - 1 > 40000) return 'At most 40000 calls to query.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'query') return 'Only query can follow the constructor.';
    const letter = args[i] && args[i][0];
    if (args[i].length !== 1 || typeof letter !== 'string' || !/^[a-z]$/.test(letter)) return 'query takes one lowercase letter.';
  }
  return null;
}

