class StreamChecker {
  constructor(words) {
    this.root = { children: {}, isWord: false };
    this.stream = [];
    this.maxLength = 0;
    for (const word of words) {
      let node = this.root;
      for (let i = word.length - 1; i >= 0; i--) {
        const ch = word[i];
        if (!node.children[ch]) {
          node.children[ch] = { children: {}, isWord: false };
        }
        node = node.children[ch];
      }
      node.isWord = true;
      this.maxLength = Math.max(this.maxLength, word.length);
    }
  }

  query(letter) {
    this.stream.push(letter);
    let node = this.root;
    const stop = Math.max(0, this.stream.length - this.maxLength);
    for (let i = this.stream.length - 1; i >= stop; i--) {
      node = node.children[this.stream[i]];
      if (!node) {
        return false;
      }
      if (node.isWord) {
        return true;
      }
    }
    return false;
  }
}

