function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const alphabetSize = size === 'large' ? pick(2, 26) : pick(2, 4);
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, alphabetSize);
  const letter = () => alphabet[Math.floor(rand() * alphabet.length)];
  const word = length => Array.from({ length }, letter).join('');
  const calls = size === 'large' ? 499 : pick(1, 15);
  // Large streams sometimes repeat the first letter for a while so the 200-letter word can match.
  const runStart = size === 'large' && rand() < 0.5 ? pick(0, 200) : -1;
  const stream = Array.from({ length: calls }, (_, i) => runStart >= 0 && i >= runStart && i < runStart + 220 ? alphabet[0] : letter());
  const words = [];
  if (size === 'large') {
    // Random words long enough to match rarely, plus pieces of the stream that are sure to match.
    const shortest = Math.ceil(Math.log(2000) / Math.log(alphabetSize));
    const noise = pick(20, 300);
    for (let i = 0; i < noise; i++) words.push(word(pick(shortest, shortest + 20)));
    const pieces = pick(10, 120);
    for (let i = 0; i < pieces; i++) {
      const end = pick(shortest, calls);
      words.push(stream.slice(Math.max(0, end - pick(shortest, shortest + 12)), end).join(''));
    }
    words.push(alphabet[0].repeat(200));
  } else {
    const count = pick(1, 4);
    for (let i = 0; i < count; i++) words.push(word(pick(1, 4)));
  }
  const operations = ['StreamChecker'];
  const args = [[words]];
  for (const ch of stream) {
    operations.push('query');
    args.push([ch]);
  }
  return [operations, args];
}
